plugins {
    id("hopa.kotlin-jvm")
    alias(libs.plugins.kotlin.serialization)
    `java-test-fixtures`
}

// Generated knowledge only: the app catalog, the approval policy data and the
// prompt rules. Every file here except the hand-written Knowledge files starts
// with "// Generated by"; the sources are contracts/ and
// services/brain/knowledge, and the build scripts write here. The hand-written
// files are the value and the source the engine reads, so a fetched snapshot can
// replace the bundled one later. Nothing in this module may depend on anything
// else.

dependencies {
    implementation(libs.kotlinx.serialization.json)

    testImplementation(libs.junit)
}

sourceSets {
    // TestKnowledge loads /knowledge.v1.json; the file already sits in the
    // module's test resources, so the fixtures jar carries that copy.
    testFixtures {
        resources.srcDir(file("src/test/resources"))
    }
}
